/// <summary>
/// designed from NDX
/// </summary>
/// <param name = "_formRun">_formRun</param>
public void NDXsetMagentoOPKEnabled(FormRun _formRun)
{
    InventTable inventTable = _formRun.dataSource(formDataSourceStr(EcoResProductDetailsExtended, InventTable)).cursor();
    FormControl NDXOpenProductInOPKCatalog = _formRun.design().controlName(formControlStr(EcoResProductDetailsExtended, NDXOpenProductInOPKCatalog));

    NDXOpenProductInOPKCatalog.enabled(false);
    if(inventTable.NDX_ShowItemInOnlineCatalog && NDXMagentoProducts::find(inventTable.NDXModelNumber))
    {
        NDXOpenProductInOPKCatalog.enabled(true);
    }  
}
